INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13q','0493x13q','x13q','0493x13q','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Turnover des orphelins de fermeture cinétique','Ablation post-x13p ajoutant un traitement dédié des particules orphelines de la fermeture cinétique via MPCD_X10_KINETIC_INTERFACE_ORPHAN_TURNOVER.','ABLATION','TRANSPORT_SURFACE','Expérience de confinement post-x13n; absente du commit qualifié 7655b81','A','2026-08-31',NULL,NULL,'Sémantique détaillée conservée par le README/patcher historiques; V4.20 n’en déduit pas davantage que ce qu’attestent le nom et le flag.','doc/README_0493x13q_orphan_turnover.txt',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13r','0493x13r','x13r','0493x13r','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Refroidissement direct des cellules interfaciales','Ablation imposant un refroidissement quasi-nul sur les cellules immédiatement identifiées interfaciales afin d’isoler le rôle de l’agitation thermique dans le déficit Taylor–Culick.','ABLATION','TRANSPORT_SURFACE','Rejetée: fermeture discontinue et dépendante du masque; supersédée par x13t','A','2026-08-31',NULL,NULL,NULL,'doc/README_0493x13r_interface_cell_cooling.txt',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13s','0493x13s','x13s','0493x13s','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Refroidissement interfacial anisotrope','Ablation supprimant surtout l’agitation thermique normale tout en gardant une fraction tangentielle et une profondeur de couche configurable.','ABLATION','TRANSPORT_SURFACE','Rejetée comme fermeture générale; supersédée par x13t','A','2026-08-31',NULL,NULL,NULL,'doc/README_0493x13s_interface_anisotropic_cooling.txt',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13t','0493x13t','x13t','0493x13t','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Refroidissement progressif unifié','Remplace les seuils abrupts x13r/s par fT=min(fGamma,fthin), combinant distance à interface et loi d’épaisseur locale; améliore G_TC mais ne ferme pas la population diffuse.','ABLATION','TRANSPORT_SURFACE','Expérience causale rejetée comme chemin général après x13zd','A','2026-08-31',NULL,NULL,'À RGamma/h=4, la campagne historique améliore G_TC mais laisse une population diffuse; le chemin est ensuite invalidé sur gouttes fermées.','doc/README_0493x13t_unified_progressive_interface_cooling.txt',NULL);
