INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13v','0493x13v','x13v','0493x13v','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Séparation position one-for-one / swap vitesse','Sépare explicitement la relocalisation spatiale x10u du swap full-vector x10v afin de mesurer leurs contributions respectives sous x13t.','ABLATION','TRANSPORT_SURFACE','Expérimental/rejeté; outil causal de séparation de x10u et x10v','A','2026-08-31',NULL,NULL,NULL,'doc/README_0493x13v_x13t_split_one_for_one.txt',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13w','0493x13w','x13w','0493x13w','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Escape → inactive → reseed local','Convertit un crossing sortant confirmé en slot inactif puis recrée une particule de même masse/type côté liquide; le mécanisme ferme les fuites mais transporte artificiellement le support vers l’intérieur.','ABLATION','TRANSPORT_SURFACE','Rejeté: contraction artificielle du support de phase','A','2026-08-31',NULL,NULL,NULL,'doc/README_0493x13w_escape_reseed.txt',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13w-fix3','0493x13w-fix3','x13w-fix3','0493x13w-fix3','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Reseed sur moyenne pré-échappement','Corrige le biais de vitesse de reseed en utilisant une moyenne locale pré-échappement plutôt que la moyenne survivante après sélection des vitesses sortantes.','FIX','TRANSPORT_SURFACE','Correctif utilisé dans x13zd; mécanisme x13w reste invalidé physiquement','A','2026-08-31',NULL,NULL,NULL,'scripts/run_0493x13w_fix3_tc_preescape_mean.sh',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13x','0493x13x','x13x','0493x13x','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Sweep de rétention probabiliste','Reconnecte la fraction de rétention r pour interpoler entre hard retention et crossing naturel, puis mesure conjointement G_TC et fuite/diffusion du support.','ABLATION','TRANSPORT_SURFACE','Aucun compromis robuste vitesse/confinement; non production','A','2026-08-31',NULL,NULL,NULL,'analyze_0493x13x_tc_retention_sweep.m',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13z','0493x13z','x13z','0493x13z','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Exploration de changements de grille','Teste des représentations de grille alternatives qui peuvent augmenter G_TC mais changent aussi bruit/statistique et physique subgrid; aucun cas ne constitue à lui seul une convergence.','BENCHMARK','TRANSPORT_SURFACE','Gains séduisants mais non suffisants pour validation','A','2026-08-31',NULL,NULL,NULL,'rapport_mpcd_incompressible_complete_0493x13_surface_final_310826.tex',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13za','0493x13za','x13za','0493x13za','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Comparaison gouttes oscillantes entre grilles','Compare n=2/3/4 sur grilles 256 et 320 avec la chaîne qualifiée pour isoler l’effet de représentation avant d’attribuer le gain Taylor–Culick à une fermeture.','DIAGNOSTIC','TRANSPORT_SURFACE','Diagnostic de dépendance de grille de la dynamique capillaire','A','2026-08-31',NULL,NULL,NULL,'scripts/run_0493x13za_oscillating_drop_grid_compare.sh',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13zb','0493x13zb','x13zb','0493x13zb','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Comparaison Young–Laplace entre grilles','Tente une comparaison mécanique Young–Laplace entre représentations de grille et révèle une forte sensibilité du protocole de baseline/pression à forte sigma.','DIAGNOSTIC','TRANSPORT_SURFACE','Diagnostic; la régression brute forte-sigma n’est pas une mesure physique robuste de sigma_eff','A','2026-08-31',NULL,NULL,NULL,'scripts/run_0493x13zb_young_laplace_grid_compare.sh',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13zb2','0493x13zb2','x13zb2','0493x13zb2','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Baseline sigma=0 courte pour comparaison de grille','Sous-étape de protocole qui raccourcit la baseline sigma=0 afin de limiter la dérive géométrique de la goutte libre pendant la comparaison Young–Laplace.','DIAGNOSTIC','TRANSPORT_SURFACE','Essai de protocole; ne ferme pas le biais de baseline','A','2026-08-31',NULL,NULL,NULL,'scripts/run_0493x13zb2_young_laplace_grid_compare_short_s0.sh',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13zb3','0493x13zb3','x13zb3','0493x13zb3','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Audit de stabilité et rebaseline Young–Laplace','Analyse la stabilité des baselines et relance uniquement les références nécessaires; met en évidence qu’une longue goutte sigma=0 n’est pas un état mécanique apparié stable.','DIAGNOSTIC','TRANSPORT_SURFACE','Diagnostic de baseline; motive l’abandon de la référence libre longue sigma=0','A','2026-08-31',NULL,NULL,NULL,'scripts/analyze_0493x13zb3_baseline_stability.py',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13zc','0493x13zc','x13zc','0493x13zc','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Mécanique statique de goutte versus grille','Analyse rayon effectif, courbure active, clipping et métriques mécaniques sur les deux grilles pour expliquer les décalages de fréquence et séparer géométrie de tension effective.','DIAGNOSTIC','TRANSPORT_SURFACE','Diagnostic de représentation; R_eff plus petit sur grille fine explique une part majeure du shift fréquentiel','A','2026-08-31',NULL,NULL,NULL,'scripts/analyze_0493x13zc_static_drop_grid_mechanics.py',NULL);
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x13zd','0493x13zd','x13zd','0493x13zd','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Validation croisée décisive et rollback','Teste la meilleure fermeture expérimentale x13t+x13w-fix3 sur gouttes oscillantes n=2/3/4 et deux grilles; montre contraction du support et dégradation modale, puis motive le retour au tag 7655b81.','QUALIFICATION','TRANSPORT_SURFACE','Invalide x13t+x13w comme chemin général; point de production ramené à surf-tension-qualified-x13h-20260831','A','2026-08-31',NULL,NULL,'Le commit 3daf archive les fichiers expérimentaux après coup; il est enregistré comme preuve, pas comme commit d’introduction.','rapport_mpcd_incompressible_complete_0493x13_surface_final_310826.tex',NULL);
